                      value: Data.recipients[recipientType].inputVal,
                      oninput: (e) => handleInput(e, recipientType),
                      placeholder: totalRecipients() >= MAX_RECIPIENTS ? 'Max recipients reached' : '',
                      disabled: totalRecipients() >= MAX_RECIPIENTS,
